'use strict';

class PlaylistCursor {
  constructor(entries, notify) {
    if (!Array.isArray(entries) || entries.some(entry => typeof entry !== 'string' || entry.length === 0)) {
      throw new TypeError('entries must be non-empty strings');
    }
    if (typeof notify !== 'function') throw new TypeError('notify must be a function');
    this._entries = entries.slice();
    this._notify = notify;
    this._running = false;
    this._index = entries.length === 0 ? -1 : 0;
    this._descriptor = null;
  }

  start() {
    if (this._running || this._entries.length === 0) return false;
    this._running = true;
    this._notify({ type: 'started', index: this._index });
    return true;
  }

  stop() {
    if (!this._running) return false;
    this._running = false;
    this._notify({ type: 'started', index: this._index });
    return true;
  }

  select(index) {
    if (!Number.isInteger(index) || index < 0 || index >= this._entries.length) {
      throw new RangeError('index out of range');
    }
    this._index = index;
    this._notify({ type: 'selected', index });
    return this._entries[index];
  }

  setDescriptor(descriptor) {
    if (descriptor === null) {
      this._descriptor = null;
      return null;
    }
    if (!descriptor || typeof descriptor !== 'object' ||
        typeof descriptor.title !== 'string' || typeof descriptor.author !== 'string') {
      throw new TypeError('invalid descriptor');
    }
    this._descriptor = { title: descriptor.title, author: descriptor.author };
    return { ...this._descriptor };
  }

  snapshot() {
    return {
      entries: this._entries.slice(),
      running: this._running,
      index: this._index,
      descriptor: this._descriptor === null ? null : { ...this._descriptor }
    };
  }
}

module.exports = { PlaylistCursor };

