'use strict';

const assert = require('node:assert');
const api = require('./solution');
assert.deepStrictEqual(Object.keys(api), ['PlaylistCursor']);
const { PlaylistCursor } = api;

const sourceEntries = ['one', 'two', 'three'];
const events = [];
const cursor = new PlaylistCursor(sourceEntries, event => events.push(event));
sourceEntries[0] = 'mutated';
assert.deepStrictEqual(cursor.snapshot(), {
  entries: ['one', 'two', 'three'], running: false, index: 0, descriptor: null
});

assert.strictEqual(cursor.start(), true);
assert.deepStrictEqual(events, [{ type: 'started', index: 0 }]);
assert.strictEqual(cursor.start(), false);
assert.strictEqual(events.length, 1);
assert.strictEqual(cursor.select(2), 'three');
assert.deepStrictEqual(events[1], { type: 'selected', index: 2 });
assert.notStrictEqual(events[0], events[1]);
assert.strictEqual(cursor.stop(), true);
assert.deepStrictEqual(events[2], { type: 'stopped', index: 2 });
assert.strictEqual(cursor.stop(), false);
assert.strictEqual(events.length, 3);
assert.strictEqual(cursor.select(1), 'two');
assert.deepStrictEqual(events[3], { type: 'selected', index: 1 });

const descriptor = { title: 'Title', author: 'Author' };
const returnedDescriptor = cursor.setDescriptor(descriptor);
assert.deepStrictEqual(returnedDescriptor, descriptor);
assert.notStrictEqual(returnedDescriptor, descriptor);
descriptor.title = 'mutated input';
returnedDescriptor.author = 'mutated return';
const firstSnapshot = cursor.snapshot();
assert.deepStrictEqual(firstSnapshot.descriptor, { title: 'Title', author: 'Author' });
firstSnapshot.entries.push('four');
firstSnapshot.descriptor.title = 'mutated snapshot';
const secondSnapshot = cursor.snapshot();
assert.deepStrictEqual(secondSnapshot, {
  entries: ['one', 'two', 'three'], running: false, index: 1,
  descriptor: { title: 'Title', author: 'Author' }
});
assert.notStrictEqual(firstSnapshot.entries, secondSnapshot.entries);
assert.notStrictEqual(firstSnapshot.descriptor, secondSnapshot.descriptor);
assert.strictEqual(cursor.setDescriptor(null), null);
assert.strictEqual(cursor.snapshot().descriptor, null);

for (const bad of [undefined, 1, 'x', {}, { title: 'x' }, { author: 'y' }, { title: 1, author: 'y' }, { title: 'x', author: 2 }]) {
  assert.throws(() => cursor.setDescriptor(bad), TypeError);
}
for (const badIndex of [-1, 3, 1.5, NaN, '1']) {
  assert.throws(() => cursor.select(badIndex), RangeError);
}
for (const badEntries of [null, {}, [''], ['ok', 1]]) {
  assert.throws(() => new PlaylistCursor(badEntries, () => {}), TypeError);
}
assert.throws(() => new PlaylistCursor([], null), TypeError);

let emptyNotifications = 0;
const empty = new PlaylistCursor([], () => { emptyNotifications += 1; });
assert.deepStrictEqual(empty.snapshot(), { entries: [], running: false, index: -1, descriptor: null });
assert.strictEqual(empty.start(), false);
assert.strictEqual(empty.stop(), false);
assert.throws(() => empty.select(0), RangeError);
assert.strictEqual(emptyNotifications, 0);

